/** Defines the narrow public and internal ROJ lookup contracts. */
export type Scenario = "RO_OPEN" | "RO_CLOSE";
export interface ValidatedLookupCommand { vin: string; scenario: Scenario; source: "COMPASS"; correlationId: string; apiKeyIdHash: string; }
export interface JourneyData { VIN?: string; dealer?: string; odometer?: number; roOpenDate?: string; roCloseDate?: string; roNumber?: string; daysDown?: number; repairCount?: number; cumulativeDays?: number; journeyStatus?: string; journeyId?: string; wiAdvisorServiceName?: string; wiAdvisorComplaint?: string; dsdiNarrative?: string; dsdiComplaint?: string; promiseDate?: string; }
export type LookupOutcome = { kind: "data"; data: JourneyData } | { kind: "no_result" } | { kind: "application_failure" } | { kind: "dependency_failure"; category: "bad_response" | "unreachable" | "timeout" | "breaker_open" | "bulkhead_full" };
export interface LookupService { execute(command: ValidatedLookupCommand): Promise<LookupOutcome>; }

import "dotenv/config";
/** Loads safe runtime configuration with conservative development defaults. */
export interface RuntimeConfig { port: number; maxRequestBytes: number; apiKeys: string[]; allowedOrigins: string[]; }
/** Parses required process settings without exposing them to clients. */
export function loadConfig(env: NodeJS.ProcessEnv = process.env): RuntimeConfig {
  const port = Number(env.PORT ?? 8000); const maxRequestBytes = Number(env.MAX_REQUEST_BYTES ?? 10240);
  const apiKeys = (env.CLIENT_API_KEYS ?? "dev-operator-key").split(",").filter(Boolean);
  if (!Number.isInteger(port) || port <= 0 || !Number.isInteger(maxRequestBytes) || maxRequestBytes <= 0 || apiKeys.length === 0) throw new Error("Invalid runtime configuration");
  return { port, maxRequestBytes, apiKeys, allowedOrigins: (env.CORS_ALLOWED_ORIGINS ?? "http://localhost:5173").split(",") };
}

import { createHash, randomUUID, timingSafeEqual } from "crypto";
import type { NextFunction, Request, RequestHandler, Response } from "express";
import type { RuntimeConfig } from "../config";
import type { LookupService, Scenario, ValidatedLookupCommand } from "../domain/contracts";
/** Writes a standardized safe failure response. */
export function safeError(res: Response, status: number, code: string, message: string, retryable = false): void { res.status(status).json({ error: { code, message, retryable }, meta: { correlationId: res.locals.correlationId } }); }
/** Attaches a caller-safe opaque correlation id to every lookup response. */
export const correlationGate: RequestHandler = (_req, res, next) => { const supplied = _req.header("x-correlation-id"); res.locals.correlationId = supplied && /^[a-zA-Z0-9-]{8,100}$/.test(supplied) ? supplied : randomUUID(); res.setHeader("X-Correlation-ID", res.locals.correlationId); next(); };
/** Rejects unsupported media before body or service processing. */
export const mediaGate: RequestHandler = (req, res, next) => { if (!req.is("application/json") || !req.accepts("application/json")) return safeError(res, 400, "INVALID_REQUEST", "Review the lookup request and try again."); next(); };
/** Validates client keys using timing-safe comparison and never stores the raw key. */
export function authorizeApiKey(config: RuntimeConfig): RequestHandler { return (req, res, next) => { const raw = req.header("x-api-key"); if (!raw) return safeError(res, 401, "MISSING_API_KEY", "Provide an authorized API key."); const valid = config.apiKeys.some((candidate) => { const a = Buffer.from(candidate); const b = Buffer.from(raw); return a.length === b.length && timingSafeEqual(a, b); }); if (!valid) return safeError(res, 403, "UNAUTHORIZED_API_KEY", "Verify authorized access."); res.locals.apiKeyIdHash = createHash("sha256").update(raw).digest("hex"); next(); }; }
/** Uses a bounded in-process development limiter behind the production limiter interface. */
export function enforceRateLimit(limit: number): RequestHandler { const counts = new Map<string, number>(); return (_req, res, next) => { const key = res.locals.apiKeyIdHash as string; const nextCount = (counts.get(key) ?? 0) + 1; counts.set(key, nextCount); if (nextCount > limit) { res.setHeader("Retry-After", "60"); return safeError(res, 429, "RATE_LIMITED", "Wait before a new lookup.", true); } next(); }; }
/** Produces a new closed-schema lookup command and discards the raw body reference. */
export function validateLookup(_service: LookupService): RequestHandler { return (req, res, next) => { const body: unknown = req.body; if (!body || typeof body !== "object" || Array.isArray(body)) return safeError(res, 400, "INVALID_REQUEST", "Review the lookup request and try again."); const value = body as Record<string, unknown>; const keys = Object.keys(value); if (keys.length !== 3 || !keys.every((key) => ["VIN", "PARAM_1", "SOURCE"].includes(key))) return safeError(res, 400, "INVALID_REQUEST", "Review the lookup request and try again."); const vin = typeof value.VIN === "string" ? value.VIN.trim() : ""; const scenario = value.PARAM_1; if (!vin || (scenario !== "RO_OPEN" && scenario !== "RO_CLOSE") || value.SOURCE !== "COMPASS") return safeError(res, 400, "INVALID_REQUEST", "Review the lookup request and try again."); res.locals.command = { vin, scenario: scenario as Scenario, source: "COMPASS", correlationId: res.locals.correlationId, apiKeyIdHash: res.locals.apiKeyIdHash } satisfies ValidatedLookupCommand; next(); }; }

import type { RequestHandler } from "express";
import type { LookupService } from "../domain/contracts";
import { safeError } from "../middleware/gates";
/** Converts classified lookup results into the documented HTTP envelope. */
export function createRojController(service: LookupService): RequestHandler { return async (_req, res) => { try { const result = await service.execute(res.locals.command); if (result.kind === "data") return void res.status(200).json({ data: result.data, meta: { correlationId: res.locals.correlationId } }); if (result.kind === "no_result") return void res.status(200).json({ data: null, meta: { correlationId: res.locals.correlationId, outcome: "no_result" } }); if (result.kind === "application_failure") return safeError(res, 500, "INTERNAL_ERROR", "Try a new lookup later."); return safeError(res, result.category === "bad_response" || result.category === "timeout" ? 502 : 503, result.category === "bad_response" || result.category === "timeout" ? "UPSTREAM_UNAVAILABLE" : "SERVICE_UNAVAILABLE", "Try a new lookup later.", true); } catch { safeError(res, 500, "INTERNAL_ERROR", "Try a new lookup later."); } }; }

import { Router, json } from "express";
import type { RuntimeConfig } from "../config";
import type { LookupService } from "../domain/contracts";
import { createRojController } from "../controllers/roj.controller";
import { authorizeApiKey, correlationGate, enforceRateLimit, mediaGate, validateLookup } from "../middleware/gates";
/** Creates the sole protected ROJ lookup route in required gate order. */
export function createRojRoute(config: RuntimeConfig, service: LookupService): Router { const router = Router(); router.post("/getROJInfo", correlationGate, mediaGate, json({ limit: config.maxRequestBytes }), authorizeApiKey(config), enforceRateLimit(config.apiKeys.length * 1000), validateLookup(service), createRojController(service)); return router; }

import cors from "cors";
import express from "express";
import type { RuntimeConfig } from "./config";
import type { LookupService } from "./domain/contracts";
import { createRojRoute } from "./routes/roj.route";
/** Bundles injectable application dependencies for testable HTTP construction. */
export interface AppDependencies { config: RuntimeConfig; lookupService: LookupService; }
/** Creates the API process with health, security headers, and the one lookup route. */
export function createApp(deps: AppDependencies): express.Express { const app = express(); app.use(cors({ origin: deps.config.allowedOrigins })); app.use((_req, res, next) => { res.setHeader("X-Content-Type-Options", "nosniff"); res.setHeader("Cache-Control", "no-store"); next(); }); app.get("/api/health", (_req, res) => res.status(200).json({ status: "ok" })); app.use("/api/csms", createRojRoute(deps.config, deps.lookupService)); app.use((_req, res) => res.status(404).json({ error: { code: "NOT_FOUND", message: "Route not found.", retryable: false } })); return app; }

import { createApp } from "./app";
import { loadConfig } from "./config";
import type { LookupService } from "./domain/contracts";
/** Provides a conservative startup service until the Compass adapter is wired. */
const unavailableService: LookupService = { async execute() { return { kind: "dependency_failure", category: "unreachable" } as const; } };
const config = loadConfig();
createApp({ config, lookupService: unavailableService }).listen(config.port, "0.0.0.0", () => console.log(`ROJ API listening on ${config.port}`));

import request from "supertest";
import { describe, expect, it } from "vitest";
import { createApp } from "../src/app";
import type { LookupService } from "../src/domain/contracts";
const config = { port: 8000, maxRequestBytes: 256, apiKeys: ["valid-key"], allowedOrigins: ["http://localhost:5173"] };
function appFor(service: LookupService) { return createApp({ config, lookupService: service }); }
describe("secure lookup gateway", () => {
 it("rejects missing keys before the service and gives correlation metadata", async () => { let calls = 0; const response = await request(appFor({ async execute() { calls++; return { kind: "no_result" }; } })).post("/api/csms/getROJInfo").set("Content-Type", "application/json").set("Accept", "application/json").send({ VIN: "VIN1", PARAM_1: "RO_OPEN", SOURCE: "COMPASS" }); expect(response.status).toBe(401); expect(response.body.error.code).toBe("MISSING_API_KEY"); expect(response.headers["x-correlation-id"]).toBeTruthy(); expect(calls).toBe(0); });
 it("rejects invalid media and closed-schema extras before lookup", async () => { let calls = 0; const app = appFor({ async execute() { calls++; return { kind: "no_result" }; } }); const media = await request(app).post("/api/csms/getROJInfo").set("x-api-key", "valid-key").set("Accept", "application/json").send("plain"); const extra = await request(app).post("/api/csms/getROJInfo").set("x-api-key", "valid-key").set("Accept", "application/json").set("Content-Type", "application/json").send({ VIN: "VIN1", PARAM_1: "RO_OPEN", SOURCE: "COMPASS", leak: true }); expect(media.status).toBe(400); expect(extra.status).toBe(400); expect(extra.body.error.message).not.toContain("leak"); expect(calls).toBe(0); });
 it("accepts a closed valid command and trims the VIN before the service", async () => { let received = ""; const response = await request(appFor({ async execute(command) { received = command.vin; return { kind: "no_result" }; } })).post("/api/csms/getROJInfo").set("x-api-key", "valid-key").set("Accept", "application/json").set("Content-Type", "application/json").send({ VIN: " VIN1 ", PARAM_1: "RO_CLOSE", SOURCE: "COMPASS" }); expect(response.status).toBe(200); expect(response.body.data).toBeNull(); expect(received).toBe("VIN1"); });
});

/** Defines API envelopes and display-safe journey fields for the operator UI. */
export type Scenario = "RO_OPEN" | "RO_CLOSE";
export interface JourneyData { VIN?: string; dealer?: string; odometer?: number; roOpenDate?: string; roCloseDate?: string; roNumber?: string; daysDown?: number; repairCount?: number; cumulativeDays?: number; journeyStatus?: string; journeyId?: string; wiAdvisorServiceName?: string; wiAdvisorComplaint?: string; dsdiNarrative?: string; dsdiComplaint?: string; promiseDate?: string; }
export interface ApiFailure { error: { code: string; message: string; retryable: boolean }; meta: { correlationId: string }; }
export interface ApiSuccess { data: JourneyData | null; meta: { correlationId: string; outcome?: "no_result" }; }

import type { ApiFailure, ApiSuccess, Scenario } from "../types";
/** Calls only the documented backend endpoint and never persists credentials. */
export async function lookup(vin: string, scenario: Scenario, apiKey: string): Promise<{ status: number; body: ApiSuccess | ApiFailure }> { const response = await fetch(`${import.meta.env.VITE_API_BASE_URL ?? ""}/api/csms/getROJInfo`, { method: "POST", headers: { "Content-Type": "application/json", Accept: "application/json", "x-api-key": apiKey }, body: JSON.stringify({ VIN: vin.trim(), PARAM_1: scenario, SOURCE: "COMPASS" }) }); return { status: response.status, body: await response.json() as ApiSuccess | ApiFailure }; }

import { describe, expect, it, vi } from "vitest";
import { lookup } from "../src/api/rojClient";
describe("ROJ client", () => { it("sends only documented headers and request fields", async () => { const fetchMock = vi.fn().mockResolvedValue({ status: 200, json: async () => ({ data: null, meta: { correlationId: "c" } }) }); vi.stubGlobal("fetch", fetchMock); await lookup(" VIN ", "RO_OPEN", "secret"); const options = fetchMock.mock.calls[0][1]; expect(JSON.parse(options.body)).toEqual({ VIN: "VIN", PARAM_1: "RO_OPEN", SOURCE: "COMPASS" }); expect(options.headers["x-api-key"]).toBe("secret"); expect(options.headers.Accept).toBe("application/json"); vi.unstubAllGlobals(); }); });
